// Quelle für decks/dbi.json (DB-Implementierung, Prof. Schätzle) – erzeugen mit: node tools/dbi-src.js
const R = String.raw;

const topics = [
  { id: "ein", label: "Einführung & Historie", color: "#f59f00" },
  { id: "spe", label: "Speicherverwaltung", color: "#12b886" },
  { id: "puf", label: "DB-Puffer", color: "#15aabf" },
  { id: "log", label: "Logging & WAL", color: "#4c6ef5" },
  { id: "rec", label: "Checkpoints & ARIES", color: "#7950f2" },
  { id: "ta", label: "Transaktionen & Serialisierbarkeit", color: "#e64980" },
  { id: "spr", label: "Sperrverfahren", color: "#fd7e14" },
  { id: "dl", label: "Deadlocks, Zeitstempel, OCC", color: "#f03e3e" },
  { id: "mv", label: "MVCC & Isolation Levels", color: "#2b8a3e" }
];

const cards = [
/* ---------- Einführung ---------- */
["ein", R`Data, Database, Query – Definitionen?`,
R`<ul><li><b>Data:</b> jede Information, die es wert ist, aufbewahrt zu werden (meist elektronisch)</li><li><b>Database:</b> Sammlung von Daten, organisiert für Zugriff und Änderung, über lange Zeit aufbewahrt</li><li><b>Query:</b> Operation, die bestimmte Daten aus der Datenbank extrahiert</li></ul><div class="tip">Der deutsche Begriff „Datenbank“ ist mehrdeutig (DBMS oder Datenbestand). Besser: <b>Datenbasis</b>.</div>`],
["ein", R`Was ist ein Datenbankmodell? Nenne Beispiele.`,
R`<p>Ein Datenmodell, das die logische Struktur einer Datenbank festlegt: wie Daten gespeichert, organisiert und manipuliert werden können.</p><p>Beispiele: relational, hierarchisch (IMS), Netzwerk (CODASYL), objektorientiert, objekt-relational, Document Model (XML, JSON).</p>`],
["ein", R`Relation und Schema?`,
R`<ul><li><b>Relation:</b> Daten als zweidimensionale Tabelle; Zeilen (Tupel) = Entitäten/Fakten, Spalten (Attribute) = deren Eigenschaften</li><li><b>Schema:</b> Beschreibung der Struktur der Daten, oft „Metadaten“ genannt</li></ul>`],
["ein", R`Was ist ein DBMS, und welche drei Fähigkeiten bietet es?`,
R`<p>Ein Werkzeug, um große Datenmengen effizient zu erzeugen und zu verwalten und sie sicher über lange Zeit persistent zu halten.</p><ol><li>Persistente Speicherung</li><li>Programmierschnittstelle</li><li>Transaktionsverwaltung</li></ol>`],
["ein", R`Was leistet die Transaktionsverwaltung eines DBMS?`,
R`<p>Sie erlaubt nebenläufigen Zugriff vieler Prozesse (Transaktionen) und sichert dabei:</p><ul><li><b>Isolation:</b> der Anschein, dass TAs nacheinander laufen</li><li><b>Atomarität:</b> TAs laufen ganz oder gar nicht</li><li><b>Resilienz:</b> Wiederherstellung nach Fehlern</li></ul>`],
["ein", R`Business Transaction vs. Datenbank-Transaktion?`,
R`<ul><li><b>Business Transaction:</b> Interaktion in der realen Welt (Geld, Waren, Informationen tauschen), deren Buchführung per Computer erfolgt → Transaction Processing (TP)</li><li><b>DB-Transaktion:</b> Gruppe von DB-Operationen (Anfragen, DML), die als Einheit ausgeführt wird, also atomar und scheinbar isoliert, nach dem ACID-Prinzip</li></ul>`],
["ein", R`Erkläre die ACID-Eigenschaften.`,
R`<ul><li><b>Atomicity:</b> ganz oder gar nicht</li><li><b>Consistency:</b> von einem konsistenten Zustand (gemäß fachlicher Integritätsbedingungen) in einen konsistenten Zustand</li><li><b>Isolation:</b> Ergebnis so, als liefe die TA allein, also vor oder nach jeder anderen TA</li><li><b>Durability:</b> Ergebnisse abgeschlossener TAs bleiben erhalten, auch bei Systemversagen</li></ul>`],
["ein", R`Nenne die Komponenten der DBMS-Architektur von oben nach unten.`,
R`<ol><li>DDL-Compiler, Query-Compiler (→ Query Plan), Transaction Manager</li><li>Execution Engine; daneben Logging &amp; Recovery sowie Concurrency Control (Lock Table)</li><li>Index-/File-/Record-Manager</li><li>Buffer Manager (Puffer)</li><li>Storage Manager</li><li>Storage</li></ol>`],
["ein", R`Warum speichert man Daten nicht einfach in Dateien?`,
R`<ul><li>aufwändige Verwaltung, vor allem nach Ändern/Löschen</li><li>ineffizienter Zugriff bei großen Datenmengen</li><li>keine Verknüpfung von Daten</li></ul>`],
["ein", R`Hierarchisches Modell vs. Netzwerk-Modell?`,
R`<ul><li><b>Hierarchisch</b> (IMS, IBM ab 1966, Apollo-Stücklisten): jeder Record-Typ hat genau einen Parent, aber mehrere Childs</li><li><b>Netzwerk</b> (CODASYL, 1969): mehrere Parents und Childs, auch Zyklen; Modellierung mit Bachman-Diagrammen, Zugriff über Zeiger (Current of Run Unit)</li></ul><p>Netzwerk-DBs wurden Anfang der 80er von relationalen DBMS verdrängt.</p>`],
["ein", R`Was zeichnet das relationale Modell aus?`,
R`<ul><li>1969/70 von <b>E. F. Codd</b> publiziert (Turing Award 1981)</li><li>mathematisch fundiert (Relationenalgebra, Tupelkalkül)</li><li>deklarative DDL und Abfragesprache</li><li>klare Trennung von logischer und physischer Ebene</li></ul><p>IBM entwickelte erst auf Kundendruck <b>System R</b> (Sprache SEQUEL → SQL), ohne Codd.</p>`],
["ein", R`Nenne Meilensteine relationaler Datenbanken.`,
R`<ul><li>IBM System R (1974) → SQL/DS (1981), DB2 (1983)</li><li>INGRES in Berkeley (1974, Stonebraker) → Sybase → MS SQL Server</li><li>Oracle (1977 SDL, Ellison; Oracle V2 1979)</li><li>POSTGRES (1985) → Postgres95 → PostgreSQL (1996); Stonebraker Turing Award 2014</li></ul>`],
["ein", R`Warum hatten objektorientierte DBMS kaum Erfolg?`,
R`<ul><li>explizite Navigationspfade über Zeiger: schnell bei direkt verknüpften Objekten, langsam bei beliebigen Abfragen</li><li>Vermischung von physischer und logischer Sicht</li><li>oft an eine Programmiersprache gebunden</li><li>Standardisierung (ODMG) nur teilweise erfolgreich</li></ul><p>Nachfolger: objekt-relationale DBMS (UDTs, Funktionen, SQL:1999).</p>`],
["ein", R`Warum spaltenorientierte DBMS für Data Warehouses?`,
R`<p>OLAP braucht sehr große Datenmengen, rein lesenden Zugriff und denormalisierte Schemata (Star/Snowflake). Spaltenorientierte Speicherung macht <b>Aggregationen über Spalten</b> sehr effizient. Meist verteilte Shared-Nothing-Systeme (Vertica, Netezza, HANA, Snowflake …).</p>`],
["ein", R`Was sind NoSQL-Datenbanken, und worauf verzichten sie oft?`,
R`<p>„Not only SQL“: spezialisierte Systeme für semistrukturierte Daten, Graphen, Streams und gigantische Datenmengen mit horizontaler Skalierung.</p><p>Sie verzichten oft ganz oder teilweise auf <b>ACID</b> und auf ein <b>Schema</b>; wichtiger sind Verfügbarkeit und Skalierbarkeit.</p><p>Arten: Key-Value (Redis, Dynamo), Dokument (MongoDB), Graph (neo4j), Datenstrom (Kafka), Multi-Model (Cosmos DB).</p>`],
["ein", R`NewSQL, hybride Systeme, Cloud-/Shared-Disk-Systeme?`,
R`<ul><li><b>NewSQL:</b> OLTP-Performance wie NoSQL, aber relational mit SQL, meist verteilt</li><li><b>Hybrid</b> (z. B. HyPer): zusätzlich OLAP-tauglich</li><li><b>Shared Disk / Cloud:</b> kein eigener Storage Manager, sondern Cloud-Speicher (z. B. S3), meist Append-Only; Speicher und Rechenleistung unabhängig skalierbar, aber höhere Latenz</li></ul>`],
["ein", R`Welches Fazit zieht die Vorlesung zur Systemauswahl?`,
R`<p>Eine Datenbasis lebt meist <b>deutlich länger</b> als die Anwendung, für die sie erstellt wurde, und wird später von weiteren Anwendungen genutzt. Das relationale Modell ist flexibler gegenüber neuen Anforderungen und gewinnt vermutlich auch bei NoSQL wieder an Bedeutung.</p>`],

/* ---------- Speicherverwaltung ---------- */
["spe", R`Beschreibe die Speicherhierarchie und wo die Grenze flüchtig/persistent liegt.`,
R`<p>CPU-Register → CPU-Cache → RAM (byteweiser Zugriff, <b>flüchtig</b>) | SSD → Festplatte → Netz-/Cloud-Speicher (blockweiser Zugriff, <b>persistent</b>).</p><p>Nach unten: größer, langsamer, billiger.</p>`],
["spe", R`Wie groß sind die Zugriffszeiten in der Speicherhierarchie (skaliert auf 1 ns = 1 s)?`,
R`<table><tr><th>Speicher</th><th>Zeit</th><th>skaliert</th></tr><tr><td>Register</td><td>1 ns</td><td>1 s</td></tr><tr><td>Cache</td><td>4 ns</td><td>4 s</td></tr><tr><td>RAM</td><td>100 ns</td><td>100 s</td></tr><tr><td>SSD</td><td>16.000 ns</td><td>4,4 h</td></tr><tr><td>HDD</td><td>2.000.000 ns</td><td>3,3 Wochen</td></tr><tr><td>Cloud</td><td>&gt; 50.000.000 ns</td><td>1,5 Jahre</td></tr></table>`],
["spe", R`Welche Eigenschaften von Festplatten (und SSDs) bestimmen das DBMS-Design?`,
R`<ul><li>Daten werden <b>blockweise</b> gelesen/geschrieben (meist 4 KB)</li><li><b>sequenzieller</b> Zugriff ist schneller als Random Access, auch bei SSDs</li><li>bei HDDs muss ein mechanischer Kopf positioniert werden</li></ul>`],
["spe", R`Welche Entwurfsziele folgen daraus für ein DBMS?`,
R`<ul><li>Anzahl der I/O-Operationen auf Sekundärspeicher <b>minimieren</b></li><li>notwendige Zugriffe möglichst <b>sequenziell</b></li><li>zusammengehörende Daten in denselben bzw. aufeinanderfolgenden Blöcken speichern</li></ul><p>Die Ziele hängen von der Technik ab und müssen bei neuer Hardware überdacht werden (z. B. Intel Optane, 2022 eingestellt).</p>`],
["spe", R`Warum nutzt ein DBMS nicht einfach den virtuellen Speicher des Betriebssystems (mmap)?`,
R`<ul><li><b>Transaktionen:</b> das OS weiß nicht, welche Bereiche eine TA geändert hat und wann sie ausgelagert werden dürfen/müssen</li><li><b>Blockierung:</b> das DBMS weiß nicht, was im RAM liegt; ein Zugriff auf Ausgelagertes blockiert den Thread</li><li>schwierige Fehlerbehandlung</li><li><b>Performanz:</b> OS-Strukturen werden zum Engpass, das DBMS kennt seine Daten besser</li></ul><p>Deshalb umgehen die meisten DBMS das OS und allozieren Ressourcen früh selbst.</p>`],
["spe", R`Was ist der Storage Manager?`,
R`<p>Die DBMS-Komponente, die die <b>Dateien</b> verwaltet: Sie kennt alle Dateien und die darin enthaltenen DB-Seiten, verwaltet freien/belegten Speicher und bildet Seiten-IDs auf physische Orte ab. Teilweise steuert sie auch das Scheduling der I/O.</p>`],
["spe", R`Hardware-Block, OS-Block, DB-Seite – was ist der Unterschied?`,
R`<ul><li><b>Hardware-Block</b> (meist 4K): Einheit, die der Speicher garantiert <b>ausfallsicher</b> schreiben kann</li><li><b>OS-Block</b> (meist 4K)</li><li><b>DB-Seite</b> (512 B bis 16K): Speichereinheit fester Größe im DBMS, mit eindeutiger ID</li></ul>`],
["spe", R`Welche Arten der Seitenverwaltung innerhalb einer Datei gibt es?`,
R`<ul><li>Heap File Organization</li><li>Tree File Organization</li><li>Index Sequential (ISAM)</li><li>Hashing File Organization</li></ul>`],
["spe", R`Wie werden Seiten in einer Heap-File-Organisation adressiert?`,
R`<ul><li><b>Eine Datei:</b> Offset = Seitengröße × Seitennummer</li><li><b>Mehrere Dateien:</b> ein <b>Seitenverzeichnis</b> kennt die Orte der Seiten (in speziellen Seiten abgelegt, inkl. Metadaten über freien Speicher)</li></ul><p>Operationen: Create, Get, Write, Delete, Iteration über alle Seiten.</p>`],
["spe", R`Was steht im Header einer DB-Seite?`,
R`<p>Seitengröße, Prüfsumme, DBMS-Version, TA-Informationen und weitere Verwaltungsinformationen (z. B. damit Seiten „self-contained“ sind, wie bei Oracle).</p>`],
["spe", R`Warum Slotted Pages statt Tupel einfach sequenziell in die Seite zu schreiben?`,
R`<p>Sequenziell geht nur mit gleich langen Tupeln und führt nach dem Löschen zu Fragmentierung.</p><p><b>Slotted Page:</b> Ein <b>Slot-Array</b> im Header speichert die Orte der Tupel; die Seite wird vom Ende her mit Tupeln gefüllt. Der Header kennt die Anzahl belegter Slots und den Beginn des Tupelspeichers.</p>`],
["spe", R`Was ist „Vacuuming“ bei Slotted Pages?`,
R`<p>Gelöschte Tupel hinterlassen Lücken. Ein <b>Hintergrundprozess</b> iteriert regelmäßig über die Seiten und reorganisiert sie bei Bedarf, damit der Platz wieder effizient nutzbar ist.</p>`],
["spe", R`Wie werden Tupel identifiziert – und darf die Anwendung diese IDs verwenden?`,
R`<p>Record Identifier, oft <b>Page-ID + Slot</b>, evtl. mit Datei. Beispiele: Postgres CTID (6 B), SQLite ROWID (8 B), Oracle ROWID (10 B), SQL Server File:Page:Slot.</p><p><b>Nein:</b> Die Anwendung darf keine Annahmen über diese IDs machen und sollte sie nicht verwenden.</p>`],
["spe", R`Wo liegen die Schema-Informationen zu einem Tupel?`,
R`<p>Nicht im Tupel. Der Tupel-Header enthält nur Metadaten wie TA-Informationen; das Schema liegt separat im <b>Data Dictionary</b>. Das DBMS interpretiert die Bytes des Tupels anhand des Schemas.</p>`],
["spe", R`Wie werden INTEGER, FLOAT, NUMERIC, VARCHAR und TIMESTAMP gespeichert?`,
R`<ul><li><b>INTEGER</b> u. Ä.: wie in C/C++</li><li><b>FLOAT/REAL:</b> IEEE 754</li><li><b>NUMERIC/DECIMAL:</b> Festkomma, proprietär je DBMS</li><li><b>VARCHAR/BLOB:</b> Header mit Länge + Byte-Array</li><li><b>TIME/DATE/TIMESTAMP:</b> 32/64-bit Integer, z. B. Mikrosekunden seit 01.01.1970</li></ul>`],
["spe", R`Warum braucht man Festkommazahlen, und was ist ihr Nachteil?`,
R`<p>Gleitkommazahlen haben Rundungsfehler (0.1 + 0.2 ≠ 0.3), das ist bei Geldbeträgen nicht tolerierbar. NUMERIC/DECIMAL rechnen ohne Rundungsfehler.</p><p><b>Nachteil:</b> langsamer (z. B. Postgres 2,34 s vs. 0,74 s für 10 Mio. Additionen).</p>`],
["spe", R`Warum sind Festkommazahlen eine Herausforderung für Standardsoftware (z. B. SAP)?`,
R`<p>Jedes DBMS implementiert Format und Rechenoperationen proprietär. Ergebnisse können sich je nach DBMS unterscheiden, vor allem bei Aggregationen. Das erfordert aufwändige Tests und Anpassungen.</p>`],
["spe", R`Wie werden Tupel mit sehr großen Attributwerten gespeichert?`,
R`<p>Das <b>Kern-Tupel</b> bleibt in der regulären Seite, der große Wert kommt in eine <b>Overflow-Page</b> (Postgres: TOAST ab 2 KB).</p><p>Sehr große BLOBs liegen in <b>externen Dateien</b> (Oracle BFILE, SQL Server FILESTREAM). Nachteil: kaum Verwaltung, nicht Teil von Transaktionen, eingeschränkte Recovery-/Backup-Garantien.</p>`],
["spe", R`Welche Nachteile hat die seitenbasierte Speicherarchitektur?`,
R`<ul><li>Fragmentierung, wenn ein Tupel nicht auf eine Seite passt</li><li>unnötige I/O: man liest eine ganze Seite für ein Tupel, oder braucht viele Tupel, die auf verschiedenen Seiten liegen</li></ul>`],
["spe", R`Wie funktioniert Log-Structured Storage?`,
R`<p>Für unveränderliche Speicher (S3, HDFS: write once, read many). Eine In-Memory-Seite protokolliert nur zwei Operationen:</p><ul><li><b>PUT</b> #id (Werte) → Insert oder Update</li><li><b>DELETE</b> #id</li></ul><p>Jede Operation wird angehängt; volle Seiten werden an das Gesamtprotokoll auf dem Sekundärspeicher angehängt.</p>`],
["spe", R`Wie liest man bei Log-Structured Storage effizient ein Tupel?`,
R`<p>Ohne Hilfe müsste man das ganze Protokoll scannen. Ein <b>Tupel-Index</b> zeigt immer auf den neuesten Eintrag: liegt er im RAM, direkt lesen; liegt er auf dem Sekundärspeicher, die Seite in den Puffer holen.</p>`],
["spe", R`Was ist Verdichtung (Compaction), und welche Nachteile hat Log-Structured Storage?`,
R`<p>Das Protokoll wächst immer weiter. Verdichtung im Hintergrund behält nur die jeweils aktuellste Operation pro Tupel; wegen Write-Once entstehen dabei neue Dateien.</p><p><b>Nachteile:</b> <b>Write Amplification</b> (unveränderte Tupel werden immer wieder neu geschrieben), Verdichtung ist aufwändig und in der Cloud teuer.</p><p>Beispiel: RocksDB (Meta, auf Basis von LevelDB).</p>`],
["spe", R`Was ist das Data Dictionary?`,
R`<p>Der <b>Systemkatalog</b>: Metadaten wie Schemata, Indexe, Rechte/Rollen, Statistiken für die Optimierung. Er liegt in systemeigenen Tabellen und unterliegt denselben TA-Garantien.</p><p>Intern wird er per prozeduralem Code gelesen (nicht per SQL); Anwender können ihn abfragen, z. B. über INFORMATION_SCHEMA (ANSI) oder <code>\d</code>, <code>SHOW TABLES</code>, <code>.tables</code>.</p>`],

/* ---------- Puffer ---------- */
["puf", R`Aufgaben und Ziele der Pufferverwaltung?`,
R`<p><b>Aufgaben:</b> Inhalte des DB-Puffers verwalten, Seiten ein- und auslagern.</p><p><b>Ziele:</b> I/O minimieren, häufig genutzte Seiten im Puffer halten, Ausgleich zwischen TA-übergreifender und TA-lokaler Optimierung.</p><p>Optimierung räumlich (wohin schreiben?) und zeitlich (wann lesen/schreiben?).</p>`],
["puf", R`Wie ist der DB-Puffer aufgebaut?`,
R`<p>Ein Array aus <b>Frames</b> (Seitenrahmen) gleicher Größe; in jeden Frame passt genau eine DB-Seite. Wird eine Seite angefordert, holt die Speicherverwaltung sie von Platte in einen freien Frame.</p>`],
["puf", R`Seitentabelle vs. Seitenverzeichnis?`,
R`<table><tr><th></th><th>Seitentabelle (Page Table)</th><th>Seitenverzeichnis</th></tr><tr><td>verwaltet</td><td>Seiten im DB-Puffer</td><td>Seiten in den DB-Dateien</td></tr><tr><td>Inhalt</td><td>Frame, Infos für Ersetzung (Zeitstempel, Zähler, Pins), Dirty-Flag</td><td>Orte der Seiten, freier Speicher</td></tr><tr><td>Lebensdauer</td><td>flüchtig</td><td>persistent, ausfallsicher</td></tr></table>`],
["puf", R`Lock vs. Latch?`,
R`<ul><li><b>Lock</b> (Sperre): koordiniert parallele Zugriffe auf DB-Objekte, im Rahmen einer Transaktion – konzeptionelles DB-Konstrukt</li><li><b>Latch:</b> schützt Datenstrukturen im Hauptspeicher bei Multithreading – Implementierungsebene (sonst „Mutex“ genannt)</li></ul>`],
["puf", R`Welche Vorteile haben mehrere DB-Puffer, und welche Regel gilt?`,
R`<p>Vorteile: mehr Parallelität (weniger Latch Contention), höhere Lokalität, unterschiedliche Seitengrößen und Ersetzungsstrategien je Puffer (z. B. DB2: CREATE BUFFERPOOL … für einen Tablespace).</p><p><b>Regel:</b> Eine DB-Seite darf immer nur <b>einmal</b> existieren.</p>`],
["puf", R`Was ist Pre-Fetching?`,
R`<p>Der Query-Optimizer erkennt, dass eine Anfrage viele zusammenhängende Daten braucht, und lädt sie vorab. Besonders vorteilhaft bei Sequential Scans und Index Scans (aufeinanderfolgende Blätter).</p>`],
["puf", R`Scan-Sharing – Prinzip und Unterschied zur Wiederverwendung im Puffer?`,
R`<p>Mehrere Anfragen brauchen fast dieselben Daten; spätere Anfragen „hängen sich“ an den Scan der ersten an (gleicher Cursor). Es wird der <b>Lesevorgang</b> wiederverwendet, nicht nur Seiten im Puffer. Vorteil: Seiten müssen nicht erneut geladen werden, wenn sie bereits verdrängt wurden.</p><p>DB2, SQL Server, Postgres; Oracle nur bei identischen Anfragen.</p>`],
["puf", R`Wann umgeht man den Puffer (Buffer Pool Bypass)?`,
R`<p>Bei großen sequenziellen Lesevorgängen: Sie würden den Puffer mit Seiten fluten, die niemand mehr braucht, und nützliche Seiten verdrängen. Stattdessen nutzt die Anfrage einen eigenen lokalen Puffer.</p>`],
["puf", R`Warum unterbinden die meisten DBMS den OS-Page-Cache? Welche Ausnahme gibt es?`,
R`<ul><li>Daten liegen redundant im Hauptspeicher</li><li>die Ersetzungsstrategien arbeiten gegeneinander</li><li>das DBMS weiß nicht, was tatsächlich persistent ist</li></ul><p><b>Ausnahme Postgres:</b> nutzt den OS-Cache aktiv (Empfehlung ~40 % RAM für den DB-Puffer, andere Systeme ~80 %).</p>`],
["puf", R`LFU vs. LRU?`,
R`<ul><li><b>LFU</b> (Least Frequently Used): Seite mit den wenigsten Zugriffen verdrängen. Nachteil: Alter wird ignoriert, eine früher oft genutzte Seite bleibt ewig.</li><li><b>LRU</b> (Least Recently Used): am längsten nicht genutzte Seite verdrängen; Umsetzung per Zeitstempel bzw. sortiertem Stack.</li></ul>`],
["puf", R`Wie funktioniert der Clock-Algorithmus?`,
R`<p>Jede Seite hat ein <b>Benutzt-Bit</b>, das bei Zugriff auf 1 gesetzt wird. Ein Zeiger läuft im Kreis über die Seiten: steht das Bit auf 1, wird es auf 0 gesetzt und weitergegangen; steht es auf 0, wird die Seite verdrängt.</p><p>Annäherung an LRU mit weniger Verwaltungsaufwand.</p>`],
["puf", R`Was ist Sequential Flooding, und wie hilft LRU-K?`,
R`<p>Ein sequenzieller Scan überflutet den Puffer mit Seiten, die nie wieder gebraucht werden; LRU und Clock behalten sie trotzdem als „frisch“.</p><p><b>LRU-K</b> (eine ARC-Strategie) merkt sich die letzten <b>K Zugriffszeitpunkte</b>, berechnet daraus die Intervalle und schätzt, wann der nächste Zugriff kommt.</p>`],
["puf", R`Lokale Ersetzung und Priority Hints?`,
R`<ul><li><b>Lokal:</b> Optimierung je Anfrage/TA, z. B. kleiner Ringpuffer pro Anfrage (Postgres)</li><li><b>Priority Hints:</b> Das DBMS weiß aus dem Kontext, was oft gebraucht wird (z. B. B-Baum-Wurzel) und gibt diesen Seiten höhere Priorität</li></ul>`],
["puf", R`Was ist eine Dirty Page, und wie wird sie behandelt?`,
R`<p>Eine Seite, deren Inhalt im Puffer verändert wurde. Vor ihrer Verdrängung muss sie persistent geschrieben werden, eine saubere Seite kann einfach überschrieben werden.</p><p>Deshalb <b>Background Writing:</b> Ein Hintergrundprozess durchläuft regelmäßig die Seitentabelle und schreibt Dirty Pages auf Platte, danach sind sie wieder sauber.</p>`],

/* ---------- Logging ---------- */
["log", R`Steal, No-Steal, Force, No-Force?`,
R`<ul><li><b>Steal:</b> geänderte Seite darf <b>vor</b> EOT auf Platte</li><li><b>No-Steal:</b> erst bei EOT</li><li><b>Force:</b> muss <b>bei</b> EOT auf Platte</li><li><b>No-Force:</b> darf auch <b>nach</b> EOT geschrieben werden</li></ul>`],
["log", R`Warum ist No-Steal/Force am einfachsten – und warum nutzt trotzdem fast jedes DBMS Steal/No-Force?`,
R`<p><b>Einfach:</b> Unfertige TAs stehen nie auf Platte, abgeschlossene sind garantiert persistent → kaum Recovery-Aufwand.</p><p><b>Probleme:</b></p><ul><li>No-Steal: Blockade, wenn der Puffer voller geänderter Seiten ist; Write-Set ≤ Puffergröße</li><li>Force: Lastspitzen bei EOT, unnötige Schreibvorgänge</li><li>Seitenkopien nötig, wenn zwei TAs dieselbe Seite ändern und nur eine committet</li></ul>`],
["log", R`Welche Fehlerklassen gibt es?`,
R`<ul><li><b>Transaktionsfehler:</b> Programmfehler, expliziter Abbruch, Abbruch durch das System (Deadlock) – betrifft nur die eine TA</li><li><b>Systemfehler:</b> Software- oder Hardwareausfall (Strom) – Primärspeicher verloren, Sekundärspeicher erhalten</li><li><b>Speicherfehler:</b> DB-Dateien verloren (Head-Crash, Feuer) – nur per Backup behebbar</li></ul>`],
["log", R`Was muss das DBMS im Fehlerfall garantieren?`,
R`<ul><li>Änderungen <b>nicht abgeschlossener</b> TAs werden nicht sichtbar → UNDO</li><li>Änderungen <b>abgeschlossener</b> TAs bleiben erhalten → REDO</li></ul>`],
["log", R`Ordne R1- bis R4-Recovery den Fehlerklassen zu.`,
R`<table><tr><th>Typ</th><th>Fehler</th><th>Aktion</th></tr><tr><td>R1</td><td>Transaktionsfehler</td><td>Transaction UNDO (nur diese TA)</td></tr><tr><td>R2</td><td>Systemfehler</td><td>Partial REDO abgeschlossener TAs</td></tr><tr><td>R3</td><td>Systemfehler</td><td>Global UNDO nicht abgeschlossener TAs</td></tr><tr><td>R4</td><td>Speicherfehler</td><td>Global REDO seit dem Backup</td></tr></table>`],
["log", R`Wie funktioniert das Schattenspeicher-Konzept (Shadow Paging)?`,
R`<p>Zwei Seitentabellen: <b>Master</b> (nur abgeschlossene TAs) und <b>Shadow</b> (Änderungen der laufenden TA auf Seitenkopien). Zu Beginn zeigen beide auf dieselben Seiten; bei Änderung entsteht eine Schattenkopie.</p><p>Bei COMMIT wird die <b>Database Root</b> atomar auf die Schattentabelle umgesetzt. Entspricht im Prinzip No-Steal/Force.</p>`],
["log", R`Vor- und Nachteile des Schattenspeichers?`,
R`<p><b>Vorteile:</b> Rollback = Schattentabelle löschen; Recovery = nichts zu tun.</p><p><b>Nachteile:</b> aufwändige Verwaltung (Kopie der Tabelle je TA), teurer COMMIT (alle Seiten + Tabelle schreiben), <b>Fragmentierung</b> → Garbage Collection, kein sequenzielles Lesen/Prefetching, nur eine schreibende TA.</p><p>Herkunft: System R; Varianten in LMDB, frühem CouchDB, SQLite bis 2010.</p>`],
["log", R`Was ist ein Write-Ahead Log (WAL), und welche Regel gilt?`,
R`<p>Eine sequenziell geschriebene Protokolldatei, getrennt von den DB-Dateien. Jede Änderung einer Seite im Puffer wird protokolliert.</p><p><b>Regel:</b> Der Log-Eintrag muss ins WAL geschrieben werden, <b>bevor</b> die Seite in die DB-Datei geschrieben wird. Er muss UNDO und REDO ermöglichen. Strategie: Steal/No-Force.</p>`],
["log", R`Was enthält ein WAL-Änderungseintrag?`,
R`<ul><li>Transaktions-ID</li><li>Objekt-ID (Seite, Tupel … je nach Granularität)</li><li><b>Before-Value</b> für UNDO</li><li><b>After-Value</b> für REDO</li></ul><p>Pro TA dazu BOT- und EOT-Einträge. Die Granularität muss der der Sperren entsprechen. Bei MVCC (kein Update-in-Place) entfällt der Before-Value.</p>`],
["log", R`In welcher Reihenfolge läuft ein COMMIT mit WAL ab?`,
R`<ol><li>EOT/COMMIT-Eintrag in den WAL-Puffer</li><li>Log-Einträge im WAL auf Platte speichern</li><li>erst dann der Anwendung den erfolgreichen COMMIT melden</li></ol><p>Die geänderten Seiten selbst werden irgendwann später geschrieben (No-Force).</p>`],
["log", R`Was ist Group Commit?`,
R`<p>Das Schreiben des WAL zum Ende jeder TA wird zum Flaschenhals (künstliche Serialisierung). Lösung: WAL-Schreibvorgänge mehrerer TAs bündeln und <b>mehrere WAL-Puffer</b> nutzen: Ist einer voll, wird er geschrieben, während der nächste schon befüllt wird.</p>`],
["log", R`WAL vs. Schattenspeicher – wann ist welches schneller?`,
R`<p><b>WAL</b> ist im Normalbetrieb sehr performant (sequenzielles Schreiben, Group Commit), beim Recovery langsamer (WAL einlesen, UNDO/REDO ausführen). Da Recovery selten ist, nutzen die meisten Systeme WAL.</p>`],
["log", R`Physisches vs. logisches Logging?`,
R`<table><tr><th></th><th>physisch</th><th>logisch</th></tr><tr><td>Inhalt</td><td>Werte vorher/nachher bzw. Byte-Diff</td><td>DML-Operation + Kompensationsoperation (INSERT ↔ DELETE)</td></tr><tr><td>meist für</td><td>Seiten</td><td>Tupel</td></tr><tr><td>Vorteile</td><td>einfach, einfaches Recovery</td><td>kompakt (Bulk-Updates), unabhängig von der physischen Struktur</td></tr><tr><td>Nachteile</td><td>grobe Sperren (Seiten), auch Indexänderungen loggen</td><td>Kompensation nicht trivial, R2/R4 im Single-User-Betrieb, DB muss aktionskonsistent sein</td></tr></table>`],
["log", R`Was ist physiological Logging?`,
R`<p>„Physical-to-a-page, logical-within-a-page“: Log-Einträge beziehen sich auf eine <b>Seite</b> (physisch), beschreiben die Änderung aber als <b>Operation</b> (logisch), z. B. <code>INSERT_TUPLE(page, slot, data)</code>, <code>UPDATE_FIELD(page, slot, offset, old, new)</code>, <code>COMPACT_PAGE(page)</code>.</p><p>Bei komplexen Seitenänderungen (B-Baum-Split) Before-/After-Images. In der Praxis von den meisten Systemen genutzt.</p>`],

/* ---------- Checkpoints & ARIES ---------- */
["rec", R`Welches Problem lösen Checkpoints?`,
R`<p>Das WAL wächst unbegrenzt; beim Recovery müsste eine riesige Datei durchlaufen werden. Ein <b>Checkpoint</b> schreibt regelmäßig Seiten aus dem Puffer auf Platte und liefert einen Anhaltspunkt, wie weit man im WAL zurückgehen muss.</p>`],
["rec", R`Warum sind einfache Checkpoints unrealistisch?`,
R`<ul><li>Warten, bis alle TAs fertig sind: aus Performancegründen unmöglich</li><li>TAs während des Checkpoints anhalten: immer noch starker Eingriff; außerdem ist ein Checkpoint bei großen Puffern nicht atomar</li></ul>`],
["rec", R`Was zeichnet Fuzzy Checkpoints aus?`,
R`<ul><li>TAs laufen <b>während</b> des Checkpoints weiter</li><li>der Checkpoint ist <b>nicht atomar</b>, er zieht sich hin</li><li>nicht unbedingt alle Dirty Pages werden geschrieben</li></ul><p>Im WAL: <b>CHECKPOINT-BEGIN</b> und <b>CHECKPOINT-END</b>, dazu ATT und DPT.</p>`],
["rec", R`Was ist eine LSN?`,
R`<p><b>Log Sequence Number:</b> global eindeutige, aufsteigende ID jedes WAL-Eintrags. Sie wird in ATT und DPT referenziert. Die Vergabe kann selbst zum Flaschenhals werden.</p>`],
["rec", R`Was enthält die Active Transaction Table (ATT)?`,
R`<p>Alle TAs, die bei CHECKPOINT-END noch aktiv sind, mit <b>txnID</b>, <b>Status</b> (R = Running, C = Committing, U = Candidate for Undo) und <b>lastLSN</b> (letzte Änderung der TA).</p><p>TAs, die nach Checkpoint-Beginn starten oder währenddessen EOT erreichen, stehen nicht darin.</p>`],
["rec", R`Warum ist der Unterschied zwischen COMMIT und EOT wichtig?`,
R`<p>Eine TA ist erst bei <b>EOT</b> wirklich abgeschlossen, dann sind auch Aufräumarbeiten wie das Freigeben von Locks erledigt. Eine TA nach COMMIT, aber vor EOT steht noch in der ATT (Status C); beim Recovery müssen die Aufräumarbeiten nachgeholt werden.</p>`],
["rec", R`Was enthält die Dirty Page Table (DPT), und wozu dient recLSN?`,
R`<p>Alle Seiten, die bei CHECKPOINT-END noch dirty sind (geändert, nicht geschrieben), jeweils mit <b>recLSN</b> = LSN der <b>ersten</b> Änderung, die die Seite dirty gemacht hat.</p><p>Nur diese Seiten brauchen REDO; recLSN sagt, wie weit man dafür im WAL zurück muss.</p>`],
["rec", R`Wie oft sollte man Checkpoints durchführen?`,
R`<p>Kompromiss: selten → langes, aufwändiges Recovery; oft → beeinträchtigt den Normalbetrieb. Deshalb in den meisten DBMS parametrisierbar.</p>`],
["rec", R`Was muss beim Recovery für abgeschlossene bzw. nicht abgeschlossene TAs passieren – und warum?`,
R`<ul><li><b>Abgeschlossene TAs:</b> REDO der Änderungen, die nicht persistent waren – wegen <b>No-Force</b></li><li><b>Nicht abgeschlossene TAs:</b> UNDO der Änderungen, die schon auf Platte waren – wegen <b>Steal</b></li></ul>`],
["rec", R`Was ist ARIES, und was sind seine Eigenschaften?`,
R`<p><b>Algorithm for Recovery and Isolation Exploiting Semantics</b>, IBM DB2, Anfang der 90er.</p><ul><li>unterstützt Steal/No-Force mit WAL und Fuzzy Checkpoints</li><li>verkraftet Fehler während des Recovery: REDO stellt den vollen Zustand vor dem Crash her (<b>Repeating History</b>), jedes UNDO wird protokolliert</li><li>REDO physisch auf Seitenbasis, UNDO logisch</li></ul>`],
["rec", R`Welche Verwaltungsinformationen nutzt ARIES?`,
R`<ul><li><b>ATT</b> und <b>DPT</b> (am Ende jedes Checkpoints)</li><li>pro Seite: <b>recLSN</b> (erste Änderung, die sie dirty machte), <b>pageLSN</b> (letzte Änderung)</li><li>global: <b>flushedLSN</b> (letzter gespeicherter WAL-Eintrag), <b>MasterRecord</b> (LSN des letzten Checkpoint-Beginns)</li></ul>`],
["rec", R`Nenne die drei Phasen von ARIES mit Start- und Endpunkt.`,
R`<ol><li><b>Analyse:</b> ab Beginn des letzten Checkpoints (MasterRecord) vorwärts; bestimmt aktive TAs und Dirty Pages</li><li><b>REDO:</b> ab der ältesten recLSN in der DPT vorwärts bis zum Ende (Repeating History)</li><li><b>UNDO:</b> vom Ende des WAL rückwärts bis zur ältesten lastLSN der TAs, die zurückgesetzt werden müssen</li></ol>`],
["rec", R`Wie aktualisiert die Analysephase ATT und DPT?`,
R`<ul><li>BOT einer TA, die nicht in der ATT ist → aufnehmen (Status UNDO)</li><li>COMMIT einer TA → Status COMMIT</li><li>EOT einer TA → aus der ATT streichen</li><li>Änderung an einer Seite, die nicht in der DPT ist → aufnehmen, recLSN = diese LSN</li></ul>`],
["rec", R`Welche Operationen wiederholt die REDO-Phase, und was passiert danach?`,
R`<p>Jede Änderung im WAL, die eine Seite in der DPT betrifft und deren LSN ≥ recLSN dieser Seite ist – auch von später abgebrochenen TAs und CLRs. Dabei kein zusätzliches Logging, kein erzwungenes Schreiben.</p><p>Danach: Für TAs mit Status COMMIT EOT schreiben und aus der ATT löschen, WAL-Puffer flushen.</p>`],
["rec", R`Was macht die UNDO-Phase, und was ist ein CLR?`,
R`<p>Sie läuft vom Ende des WAL rückwärts und macht alle TAs mit Status UNDO rückgängig.</p><p>Nach jeder UNDO-Operation wird ein <b>Compensation Log Record (CLR)</b> geschrieben. Er verhindert, dass die Operation bei einem erneuten Crash nochmals rückgängig gemacht wird – Änderung + CLR ergeben eine „neutrale“ Operation.</p>`],

/* ---------- Transaktionen ---------- */
["ta", R`Welcher Zielkonflikt besteht bei der Ausführung von Transaktionen?`,
R`<p>Fachlich müssten TAs nacheinander laufen, um korrekt zu sein. Technisch braucht man möglichst viel Nebenläufigkeit für hohen Durchsatz und kurze Antwortzeiten. Das ACID-Prinzip löst beides.</p>`],
["ta", R`Womit werden A, C, I und D jeweils umgesetzt?`,
R`<ul><li><b>Atomicity:</b> Logging (UNDO-Logs) oder Schattenspeicher</li><li><b>Consistency:</b> korrektes Datenmodell und Integritätsbedingungen; TA sieht nur abgeschlossene TAs</li><li><b>Isolation:</b> Concurrency Control, pessimistisch (Konflikte verhindern) oder optimistisch (nachträglich auflösen)</li><li><b>Durability:</b> Logging (REDO-Logs) oder Schattenspeicher</li></ul>`],
["ta", R`Nebenläufig vs. parallel?`,
R`<ul><li><b>Nebenläufig:</b> A und B sind unabhängig bearbeitbar; egal ob A vor B, B vor A oder gleichzeitig</li><li><b>Parallel:</b> sie werden tatsächlich gleichzeitig und unabhängig ausgeführt</li></ul>`],
["ta", R`Historie vs. Schedule?`,
R`<ul><li><b>Historie:</b> die tatsächlich ausgeführte Abfolge aller Operationen mehrerer TAs, nur <b>partiell</b> geordnet (parallele Threads)</li><li><b>Schedule:</b> möglicher Ausführungsplan; in der Vorlesung <b>total</b> geordnet, z. B. $r_1(X); r_3(Y); w_1(X)$</li></ul>`],
["ta", R`Was ist ein serieller Schedule, und wie viele gibt es für n TAs?`,
R`<p>Alle TAs laufen streng hintereinander. Für $n$ TAs gibt es $n!$ verschiedene serielle Schedules.</p>`],
["ta", R`Wann stehen zwei Operationen in Konflikt?`,
R`<ol><li>sie stammen aus <b>verschiedenen</b> TAs</li><li><b>mindestens eine</b> ist eine Schreiboperation</li><li>sie betreffen <b>dasselbe</b> Datenelement</li></ol>`],
["ta", R`Lost Update – Ablauf und Schedule?`,
R`<p>Lagerbestand 100; TA1 entnimmt 20, TA2 entnimmt 30. Beide lesen 100, TA2 schreibt 70, dann TA1 80. Das Update von TA2 ist verloren (richtig wäre 50).</p>$$r_1(X);\; r_2(X);\; w_2(X);\; w_1(X)$$`],
["ta", R`Dirty Read – Ablauf und Schedule?`,
R`<p>TA1 schreibt X = 80 und bricht später ab. TA2 liest die 80 vorher und rechnet damit (55). Sie hat einen Wert benutzt, der nie gültig war (richtig: 75).</p>$$r_1(X);\; w_1(X);\; r_2(X);\; w_2(X);\; a_1$$`],
["ta", R`Non-Repeatable Read – Ablauf und Schedule?`,
R`<p>TA1 summiert X und Y, TA2 ändert beide dazwischen. TA1 sieht X vor und Y nach TA2: 220 statt 250 oder 200.</p>$$r_1(X);\; r_2(X);\; w_2(X);\; r_2(Y);\; w_2(Y);\; r_1(Y)$$`],
["ta", R`Was ist ein Phantom?`,
R`<p>Dieselbe Anfrage liefert innerhalb einer TA eine <b>andere Ergebnismenge</b>, weil eine andere TA Tupel eingefügt, gelöscht oder so geändert hat, dass sie das Prädikat (nicht mehr) erfüllen. Beispiel: Ø-Preis aller Artikel &gt; 100 € ist erst 160, dann 165, weil Artikel B auf 50 € gesenkt wurde.</p>`],
["ta", R`Was bedeutet Serialisierbarkeit?`,
R`<p>Ein beliebig verzahnter Schedule ist <b>serialisierbar</b>, wenn er denselben Datenbankzustand erzeugt wie <b>irgendein</b> serieller Schedule derselben TAs. So vermeidet man Anomalien, ohne auf Nebenläufigkeit zu verzichten.</p>`],
["ta", R`Welche Vertauschungen benachbarter Operationen sind erlaubt?`,
R`<p>Nur <b>konfliktfreie</b> Paare aus verschiedenen TAs. Konfliktbehaftete (Lese-Schreib, Schreib-Schreib auf dasselbe Element) behalten ihre Reihenfolge, weil sich sonst das Ergebnis ändern kann. Operationen innerhalb einer TA werden nie vertauscht.</p>`],
["ta", R`Konflikt-Äquivalenz und Konflikt-Serialisierbarkeit?`,
R`<ul><li><b>Konflikt-äquivalent:</b> zwei Schedules lassen sich durch konfliktfreie Tausche ineinander überführen</li><li><b>Konflikt-serialisierbar:</b> konflikt-äquivalent zu einem seriellen Schedule</li></ul><p>Konflikt-Serialisierbarkeit ist <b>hinreichend</b>, aber nicht notwendig für Serialisierbarkeit.</p>`],
["ta", R`Wie prüft man Serialisierbarkeit mit dem Abhängigkeitsgraphen?`,
R`<p>Knoten = TAs. Für jedes Konfliktpaar, in dem eine Operation von $T_i$ vor einer von $T_j$ liegt, eine Kante $T_i \to T_j$.</p><p><b>Zyklenfrei → konflikt-serialisierbar.</b> Eine topologische Sortierung liefert den äquivalenten seriellen Schedule.</p>`],
["ta", R`Warum nutzen reale DBMS weder Tauschoperationen noch Abhängigkeitsgraphen?`,
R`<p>Nicht-Serialisierbarkeit wird oft erst im Nachhinein erkannt (TAs müssten zurückgesetzt werden), und der Verwaltungsaufwand ist hoch (auch Abhängigkeiten zu abgeschlossenen TAs). Stattdessen: <b>Sperrverfahren</b>.</p>`],

/* ---------- Sperrverfahren ---------- */
["spr", R`Was macht der Scheduler, und welche Regeln gelten für Sperren?`,
R`<p>Der Scheduler koordiniert die Operationen nebenläufiger TAs und stellt sie zurück, bis ihre Ausführung die Serialisierbarkeit nicht gefährdet (Sperrentabelle).</p><ul><li>vor Lesen/Schreiben von X: Sperre $l_i(X)$ anfordern</li><li>jede Sperre wieder freigeben: $u_i(X)$</li><li>solange $T_i$ X sperrt, kann keine andere TA X sperren</li></ul>`],
["spr", R`Reichen einfaches Sperren und Freigeben für Serialisierbarkeit?`,
R`<p><b>Nein.</b> Gibt TA1 die Sperre auf X nach dem Lesen frei, kann TA2 X und Y ändern, bevor TA1 Y liest: Der Non-Repeatable Read tritt trotz Sperren auf.</p>`],
["spr", R`Was besagt das 2-Phasen-Sperrprotokoll (2PL)?`,
R`<p>In jeder TA müssen <b>alle Sperranforderungen vor der ersten Freigabe</b> erfolgen.</p><ol><li><b>Wachstumsphase:</b> Sperren anfordern</li><li><b>Schrumpfungsphase:</b> Sperren freigeben (spätestens bei TA-Ende)</li></ol><p>Garantiert konflikt-serialisierbare Schedules.</p>`],
["spr", R`Warum verhindert 2PL keinen Dirty Read?`,
R`<p>2PL geht von fehlerfreiem Betrieb aus. TA1 kann X schreiben und die Sperre in der Schrumpfungsphase freigeben, bevor sie abbricht; TA2 liest dann den ungültigen Wert.</p><p>Kaskadierendes Rollback wäre eine Lösung, ist aber zu aufwändig.</p>`],
["spr", R`Was ist striktes 2PL, und in welcher Reihenfolge läuft der Commit ab?`,
R`<p>Alle Sperren werden erst <b>am Ende der TA</b> freigegeben, nachdem ihr Überleben per Logging gesichert ist:</p><ol><li>Force-Write des COMMIT-Log-Eintrags</li><li>COMMIT durchführen</li><li>erst dann Sperren freigeben</li></ol><p>So sieht keine andere TA „schmutzige“ Daten.</p>`],
["spr", R`Wie entsteht ein Deadlock durch Sperren?`,
R`<p>TA1 hält X und will Z, TA2 hält Z und will X. Beide warten aufeinander und kommen nie weiter.</p>`],
["spr", R`SX-Sperren: Regeln und Kompatibilitätsmatrix?`,
R`<p><b>S</b> (shared, lesen) und <b>X</b> (exclusive, schreiben). Lesen braucht S oder X, Schreiben braucht X.</p><table><tr><th>gehalten \ angefordert</th><th>S</th><th>X</th></tr><tr><td>S</td><td>ja</td><td>nein</td></tr><tr><td>X</td><td>nein</td><td>nein</td></tr></table><p>Vorteil: Nur-Leser behindern sich nicht.</p>`],
["spr", R`Was ist eine Sperrkonversion (Upgrade), und welches Risiko hat sie?`,
R`<p>Eine TA hält erst S auf X und fordert später X an. Freundlicher gegenüber anderen: Sie können X zwischenzeitlich mitlesen.</p><p><b>Risiko:</b> mehr Deadlocks. Halten zwei TAs S(A) und wollen beide auf X upgraden, warten sie ewig aufeinander.</p>`],
["spr", R`Was ist eine Update-Sperre, und wie sieht die Kompatibilität aus?`,
R`<p>U = Lesesperre mit der Absicht, später zu schreiben. Danach darf keine andere TA mehr eine Sperre setzen; bestehende S-Sperren dürfen bleiben.</p><table><tr><th>gehalten \ angefordert</th><th>S</th><th>X</th><th>U</th></tr><tr><td>S</td><td>ja</td><td>nein</td><td>ja</td></tr><tr><td>X</td><td>nein</td><td>nein</td><td>nein</td></tr><tr><td>U</td><td>nein</td><td>nein</td><td>nein</td></tr></table><p>Verhindert den Upgrade-Deadlock: Die zweite TA wartet schon beim U.</p>`],
["spr", R`Warum hierarchische Sperren, und welchen Zielkonflikt lösen sie?`,
R`<p>Hierarchie: DB → Tabelle → Seite → Tupel → Attribut.</p><ul><li>grobe Sperren: wenig Verwaltung, aber wenig Parallelität</li><li>feine Sperren: viel Parallelität, aber viel Verwaltung</li></ul><p>Man braucht beide Ebenen gleichzeitig.</p>`],
["spr", R`Was sind Intention-Locks (IS, IX)?`,
R`<p>Anwartschaftssperren: Bevor auf einer Ebene S oder X gesetzt wird, muss auf <b>allen übergeordneten Knoten</b> ab der Wurzel IS (Absicht zu lesen) bzw. IX (Absicht zu schreiben) gesetzt werden. So erkennt man Konflikte zwischen Ebenen, z. B. X auf der ganzen Tabelle vs. S auf einem Tupel.</p>`],
["spr", R`Kompatibilitätsmatrix für IS, IX, S, X?`,
R`<table><tr><th>gehalten \ angefordert</th><th>IS</th><th>IX</th><th>S</th><th>X</th></tr><tr><td>IS</td><td>ja</td><td>ja</td><td>ja</td><td>nein</td></tr><tr><td>IX</td><td>ja</td><td>ja</td><td>nein</td><td>nein</td></tr><tr><td>S</td><td>ja</td><td>nein</td><td>ja</td><td>nein</td></tr><tr><td>X</td><td>nein</td><td>nein</td><td>nein</td><td>nein</td></tr></table><p>Es gibt keine Totalordnung „stärker/schwächer“ (IX und S sind unvergleichbar).</p>`],
["spr", R`Beispiel: T1 liest alle „Meierhofer“, T2 ändert Mitarbeiter 4711. Welche Sperren?`,
R`<ul><li>T1: IS auf Mitarbeiter, S auf die beiden Tupel</li><li>T2: IX auf Mitarbeiter (kompatibel zu IS), X auf Tupel 4711</li></ul><p>Wäre 4711 ein Meierhofer, müsste T2 warten, bis T1 die S-Sperre freigibt.</p>`],
["spr", R`Was ist Lock Escalation?`,
R`<p>TAs setzen zunächst Tupelsperren; ab einer bestimmten Anzahl werden sie durch eine Sperre auf der nächsthöheren Ebene (Seite, Tabelle) ersetzt, um den Verwaltungsaufwand zu begrenzen.</p>`],
["spr", R`Welche expliziten Sperren kann man in SQL setzen?`,
R`<ul><li>Tabellensperren (nicht im Standard): <code>LOCK TABLE t IN … MODE</code> (Postgres, DB2, Oracle), MySQL <code>LOCK TABLE t READ/WRITE</code>, SQL Server <code>WITH TABLOCK</code></li><li>Standard: <code>SELECT … FOR UPDATE [OF spalten]</code> (X-Sperre fürs spätere Update)</li><li>Varianten: <code>FOR SHARE</code>, <code>NOWAIT</code>, <code>SKIP LOCKED</code>, <code>WAIT n</code></li></ul>`],
["spr", R`Warum verhindern die bisherigen Sperrverfahren keine Phantome? Welche drei Ansätze gibt es?`,
R`<p>Sperren wirken nur auf <b>vorhandene</b> Objekte; neu eingefügte (oder neu ins Prädikat fallende) Tupel sind nicht gesperrt.</p><ol><li><b>Queries wiederholen:</b> Scan Sets beim Commit erneut prüfen – sehr teuer</li><li><b>Logische Sperren:</b> Prädikatsperren – Disjunktheit im Allgemeinen unentscheidbar, nur Theorie</li><li><b>Index-Sperren:</b> Wertebereiche im Index sperren – in der Praxis</li></ol>`],
["spr", R`Key-Value-, Gap- und Key-Range-Locks?`,
R`<ul><li><b>Key-Value-Lock:</b> sperrt einen Schlüssel – reicht gegen Phantome nicht</li><li><b>Gap-Lock:</b> sperrt die Lücke zwischen zwei Schlüsseln, also auch nicht existierende Werte, z. B. (14, 16)</li><li><b>Key-Range-Lock:</b> Schlüssel + folgende Lücke, z. B. [14, 16); braucht virtuelle Schlüssel für 16 … ∞</li></ul>`],
["spr", R`Was ist das Tree-Protocol, und welche Regeln hat es?`,
R`<p>Ein Sperrprotokoll für B-Bäume, das 2PL verletzt, aber trotzdem serialisierbar ist, weil jeder Zugriff von der Wurzel ausgeht.</p><ol><li>erste Sperre auf beliebigem Knoten</li><li>weitere Sperren nur auf Knoten, deren Elternknoten man gesperrt hat</li><li>Sperren dürfen jederzeit freigegeben werden</li><li>ein Knoten darf nicht erneut gesperrt werden</li></ol><p>So sperren alle TAs gemeinsame Knoten in derselben Reihenfolge.</p>`],

/* ---------- Deadlocks, Zeitstempel, OCC ---------- */
["dl", R`Deadlock-Verhütung vs. -Vermeidung? Was ist das Ziel beim Zurücksetzen?`,
R`<p><b>Verhütung (Prevention):</b> Deadlocks können gar nicht entstehen (z. B. Preclaiming). <b>Vermeidung (Avoidance):</b> bei Konflikten wird eingegriffen.</p><p>Ziel: möglichst wenige Rücksetzungen und keine „teuren“ TAs zurücksetzen.</p>`],
["dl", R`Was ist Preclaiming, und warum wird es kaum genutzt?`,
R`<p>Eine TA fordert <b>alle</b> Sperren schon bei BOT an. Bei Konflikt alles freigeben und später neu starten oder in fester Reihenfolge warten.</p><p>Nachteil: Bei BOT ist meist nur eine Obermenge der Sperren bekannt → viele Konflikte, geringe Nebenläufigkeit.</p>`],
["dl", R`Timeout und Immediate Restart – Vor- und Nachteile?`,
R`<ul><li><b>Timeout:</b> Rücksetzen nach zu langem Warten; einfach, aber optimale Zeit schwer zu wählen, viele unnötige Rücksetzungen → nur in verteilten DBMS</li><li><b>Immediate Restart / No Wait:</b> bei Konflikt sofort zurücksetzen; einfach, aber extrem viele Rücksetzungen → in der Praxis nicht genutzt</li></ul>`],
["dl", R`Wie funktioniert Wait Depth Limited (WDL)?`,
R`<p>$T_i$ fordert eine Sperre, die $T_j$ hält. Warten ist nur bis Tiefe 1 erlaubt:</p><ul><li>ist $T_j$ selbst blockiert → $T_j$ zurücksetzen, $T_i$ bekommt die Sperre</li><li>sonst: wartet schon jemand auf $T_i$ → $T_i$ zurücksetzen</li><li>sonst wartet $T_i$ auf $T_j$</li></ul>`],
["dl", R`Wait/Die vs. Wound/Wait?`,
R`<p>Jede TA hat eine Zeitmarke (ältere = kleiner). $T_i$ will eine Sperre, die $T_j$ hält:</p><table><tr><th></th><th>$T_i$ älter</th><th>$T_i$ jünger</th></tr><tr><td><b>Wait/Die</b></td><td>$T_i$ wartet</td><td>$T_i$ stirbt</td></tr><tr><td><b>Wound/Wait</b></td><td>$T_j$ wird zurückgesetzt (verwundet)</td><td>$T_i$ wartet</td></tr></table><p>In beiden Fällen wird immer die <b>jüngere</b> TA zurückgesetzt.</p>`],
["dl", R`Warum behält eine zurückgesetzte TA ihre alte Zeitmarke? Was ist der Nachteil von Wait/Die und Wound/Wait?`,
R`<p>Statische Zeitmarken verhindern <b>Verhungern</b>: Die TA wird mit jedem Neustart relativ älter und setzt sich irgendwann durch.</p><p>Nachteil: Es wird zurückgesetzt, obwohl evtl. gar kein Deadlock vorliegt. Wound/Wait schnitt in Simulationen besser ab.</p>`],
["dl", R`Wie erkennt man Deadlocks mit einem Wartegraphen?`,
R`<p>Aus der Sperrentabelle: Knoten = TAs, Kante $T_i \to T_j$, wenn $T_i$ auf $T_j$ wartet. <b>Zyklus = Deadlock.</b></p><p>Zyklensuche bei jedem Sperrkonflikt oder periodisch. Auflösung durch Rücksetzen eines Opfers, am besten der TA mit den <b>wenigsten Sperren</b>. Greift nur bei echten Deadlocks.</p>`],
["dl", R`Wie skaliert die Deadlock-Wahrscheinlichkeit, und welche Verfahren sind deshalb meist im Vorteil?`,
R`<p>In Modellen quadratisch mit der Zahl paralleler TAs und mit der vierten Potenz der Zahl der Sperren (real eher stärker). Immer gilt: Deadlocks &lt; Sperrkonflikte. Deshalb sind Verfahren im Vorteil, die Deadlocks tatsächlich <b>erkennen</b>.</p>`],
["dl", R`Grundidee des Zeitstempelverfahrens?`,
R`<p>Keine Sperren. Jede TA bekommt beim Start einen aufsteigenden Zeitstempel $TS(T_i)$; jedes Objekt X speichert $R\text{-}TS(X)$ und $W\text{-}TS(X)$ (letzter Leser/Schreiber). Die Serialisierungsreihenfolge ist die Zeitstempelreihenfolge.</p>`],
["dl", R`Zeitstempelverfahren: Regel beim Lesen?`,
R`<p>Ist $W\text{-}TS(X) &gt; TS(T_i)$, hat eine jüngere TA X bereits geändert – eine Änderung „aus der Zukunft“ → $T_i$ neu starten.</p><p>Sonst lesen und $R\text{-}TS(X) = \max(R\text{-}TS(X), TS(T_i))$ setzen.</p>`],
["dl", R`Zeitstempelverfahren: Regel beim Schreiben?`,
R`<p>Ist $R\text{-}TS(X) &gt; TS(T_i)$ oder $W\text{-}TS(X) &gt; TS(T_i)$, hat eine jüngere TA X schon gelesen oder geschrieben → $T_i$ neu starten.</p><p>Sonst schreiben und $W\text{-}TS(X) = TS(T_i)$ setzen.</p>`],
["dl", R`Was besagt die Thomas Write Rule?`,
R`<ul><li>$TS(T_i) &lt; R\text{-}TS(X)$: eine jüngere TA hat X gelesen → $T_i$ zurücksetzen</li><li>$TS(T_i) &lt; W\text{-}TS(X)$: eine jüngere TA hat X überschrieben → Schreiboperation von $T_i$ einfach <b>weglassen</b> und weitermachen</li></ul><p>Vermeidet unnötige Rücksetzungen, verletzt aber die Zeitstempelreihenfolge (dann nicht mehr konflikt-serialisierbar).</p>`],
["dl", R`Vor- und Nachteile des Zeitstempelverfahrens?`,
R`<p><b>Vorteile:</b> konflikt-serialisierbar (ohne Thomas Write Rule), keine Deadlocks.</p><p><b>Nachteile:</b> Verhungern langer TAs; jede Leseoperation muss auch schreiben (Zeitstempel); Kopien in den privaten Workspace.</p><p>Keine bekannte DB nutzt es direkt, aber es ist Basis für MVCC und OCC.</p>`],
["dl", R`Wann sind optimistische Verfahren sinnvoll, und wie laufen sie ab?`,
R`<p>Wenn Konflikte selten sind (kurze TAs, viele Nur-Leser, disjunkte Daten).</p><ol><li><b>Lesephase:</b> Arbeit auf privaten Kopien, Read-Set RS und Write-Set WS ($WS \subseteq RS$)</li><li><b>Validierungsphase:</b> Konflikte prüfen, ggf. zurücksetzen</li><li><b>Schreibphase:</b> Änderungen persistent machen (erst Logging)</li></ol>`],
["dl", R`BOCC vs. FOCC?`,
R`<table><tr><th></th><th>BOCC (backward)</th><th>FOCC (forward)</th></tr><tr><td>prüft gegen</td><td>bereits validierte TAs</td><td>noch laufende TAs</td></tr><tr><td>Vergleich</td><td>RS der validierenden TA ∩ WS der während ihrer Lesephase validierten TAs</td><td>WS der validierenden TA ∩ RS der laufenden TAs</td></tr><tr><td>bei Konflikt</td><td>nur die validierende TA zurücksetzen</td><td>freie Wahl, Arbeitsverlust minimieren</td></tr></table>`],
["dl", R`Welche Probleme hat BOCC?`,
R`<ul><li><b>Unechte Konflikte:</b> Hat die TA bereits die aktuelle Version gelesen, ist der Abbruch unnötig (Abhilfe: Versionszähler)</li><li><b>Starvation:</b> nur die validierende TA kann zurückgesetzt werden; lange TAs mit großem Read-Set scheitern immer wieder</li></ul>`],
["dl", R`Vor- und Nachteile optimistischer Verfahren?`,
R`<p><b>Vorteile:</b> keine Deadlocks, höhere Parallelität (kein Blockieren).</p><p><b>Nachteile:</b> evtl. viele Rücksetzungen, die teurer sind als bei 2PL (erst nach der Ausführung); Aufwand für private Kopien; schwierige Implementierung (Seiten, Indexe).</p>`],

/* ---------- MVCC & Isolation ---------- */
["mv", R`Grundidee von MVCC?`,
R`<p>Das DBMS hält mehrere physische Versionen eines logischen Objekts. Schreiben erzeugt eine <b>neue Version</b> (nie überschreiben); Lesen liefert die neueste Version, die beim <b>Start</b> der TA existierte.</p><ul><li>Schreiber blockieren keine Leser</li><li>Leser blockieren keine Schreiber</li></ul><p>Bonus: „Zeitreisen“ in die Vergangenheit möglich.</p>`],
["mv", R`Wie bestimmt MVCC, welche Version eine TA sieht?`,
R`<p>Jede Version hat <b>Begin-TS</b> (TA, die sie erzeugt hat) und <b>End-TS</b> (TA, die die nächste Version erzeugt hat). Eine TA sieht die Version mit Begin-TS ≤ TS(TA) &lt; End-TS – aber nur, wenn die erzeugende TA laut <b>TA-Statustabelle</b> abgeschlossen ist. Das ergibt Repeatable Reads.</p>`],
["mv", R`Was passiert bei MVCC, wenn zwei TAs dasselbe Objekt schreiben wollen?`,
R`<p>Die spätere TA muss <b>warten</b>, bis die erste abgeschlossen ist (Snapshot Isolation). So werden Objekte in der Reihenfolge der Zeitstempel geändert. Auf Stufe Serializable müsste sie abbrechen.</p>`],
["mv", R`Was garantiert Snapshot Isolation – und was nicht?`,
R`<p>Jede TA sieht ein konsistentes Bild der Daten zum Zeitpunkt TS(TA): Repeatable Reads, keine Änderungen laufender TAs, keine Phantome.</p><p><b>Aber:</b> Die <b>Write Skew Anomaly</b> ist möglich. Snapshot Isolation liegt unter Serializable.</p>`],
["mv", R`Erkläre die Write Skew Anomaly.`,
R`<p>TA1: „mach alle roten Kreise blau“, TA2: „mach alle blauen Kreise rot“. Beide lesen denselben Snapshot und ändern <b>disjunkte</b> Objekte, also kein Schreibkonflikt. Ergebnis: Farben vertauscht – kein serieller Schedule erzeugt das (dort wären am Ende alle gleich).</p><p>Nur auf Stufe <b>Serializable</b> vermieden.</p>`],
["mv", R`Welche Architekturentscheidungen umfasst MVCC?`,
R`<ol><li>Concurrency-Control-Protokoll (Zeitstempel, OCC oder 2PL auf Versionen)</li><li>versionierte Speicherung</li><li>Garbage Collection</li><li>Index-Management</li><li>Löschverfahren</li></ol>`],
["mv", R`Append-Only, Time-Travel, Delta Storage?`,
R`<ul><li><b>Append-Only:</b> alle Versionen im selben Tablespace, per Zeiger verkettet</li><li><b>Time-Travel:</b> aktuelle Version in der Haupttabelle, alte werden in eine separate Tabelle kopiert (typisch bei nachgerüstetem MVCC, z. B. SQL Server)</li><li><b>Delta Storage:</b> nur die <b>geänderten Attribute</b> der Vorversion kommen in einen Delta-Speicher – speichereffizient, heute am verbreitetsten (SQL Server, Oracle, CockroachDB)</li></ul>`],
["mv", R`Oldest-to-Newest vs. Newest-to-Oldest?`,
R`<ul><li><b>O2N:</b> neue Versionen ans Ende der Kette; Index zeigt auf die älteste → Kette durchlaufen bis zur neuesten</li><li><b>N2O:</b> Index zeigt auf die neueste → schneller Zugriff, aber <b>alle Indexe</b> müssen bei jeder neuen Version angepasst werden</li></ul>`],
["mv", R`Wann darf eine alte Version per Garbage Collection gelöscht werden?`,
R`<p>Wenn keine laufende TA sie mehr sehen kann: Hat die <b>älteste aktive TA</b> einen TS &gt; End-TS der Version, kann sie freigegeben werden.</p>`],
["mv", R`Background Vacuuming, Cooperative Cleaning, TA-bezogene GC?`,
R`<ul><li><b>Background Vacuuming:</b> Hintergrundprozess scannt alle Daten; optimiert mit Dirty Block Bitmap</li><li><b>Cooperative Cleaning:</b> bei O2N geben TAs beim Durchlaufen der Kette alte Versionen frei; selten genutzte Objekte brauchen zusätzlich Vacuuming</li><li><b>TA-bezogen:</b> jede TA sammelt ihre alten Versionen und übergibt sie beim COMMIT mit ihrem Begin-TS an den GC</li></ul>`],
["mv", R`Sekundärindexe bei MVCC: physische vs. logische Zeiger?`,
R`<ul><li><b>Physische Zeiger:</b> direkt auf die Version bzw. Kettenanfang – schneller Zugriff, aber bei vielen Sekundärindexen müssen alle bei jeder neuen Version angepasst werden</li><li><b>Logische Zeiger</b> (Indirektion über den Primärindex): langsamerer Zugriff, aber Anpassung „gratis“</li></ul><p>Praxisbeispiel: Uber wechselte wegen des Postgres-Index-Managements zurück zu MySQL.</p>`],
["mv", R`Nenne die SQL-92-Isolation-Levels und die möglichen Anomalien.`,
R`<table><tr><th>Level</th><th>Dirty Read</th><th>Non-Repeatable</th><th>Phantom</th></tr><tr><td>Serializable</td><td>nein</td><td>nein</td><td>nein</td></tr><tr><td>Repeatable Read</td><td>nein</td><td>nein</td><td>evtl.</td></tr><tr><td>Read Committed</td><td>nein</td><td>evtl.</td><td>evtl.</td></tr><tr><td>Read Uncommitted</td><td>evtl.</td><td>evtl.</td><td>evtl.</td></tr></table>`],
["mv", R`Wie werden die Isolation Levels mit Sperren umgesetzt?`,
R`<ol><li><b>Serializable:</b> striktes 2PL, alle Sperren sofort, plus Index-Sperren</li><li><b>Repeatable Read:</b> wie 1, aber ohne Index-Sperren</li><li><b>Read Committed:</b> wie 2, aber Lesesperren werden sofort freigegeben</li><li><b>Read Uncommitted:</b> wie 3, aber gar keine Lesesperren</li></ol>`],
["mv", R`Wie setzt man den Isolation Level, und was sind typische Defaults?`,
R`<p><code>SET TRANSACTION ISOLATION LEVEL …;</code> (alle TAs) bzw. <code>BEGIN TRANSACTION ISOLATION LEVEL …;</code></p><p>Defaults: Postgres, Oracle, SQL Server, SAP HANA <b>Read Committed</b>; MySQL <b>Repeatable Read</b>; CockroachDB, VoltDB <b>Serializable</b>. Oracle kann maximal Snapshot Isolation.</p>`],
["mv", R`Warum bieten DBMS schwächere Isolation Levels an, und welches Risiko zeigt der Silk-Road-Fall?`,
R`<p>Serializable reduziert die Nebenläufigkeit; schwächere Stufen bringen Performance gegen Konsistenz.</p><p><b>Silk Road (2012):</b> Mit über 140 schnell aufeinanderfolgenden Transaktionen wurde das Auszahlungssystem überlistet und ~50.000 Bitcoin abgezogen – ein Beispiel für fehlende Isolation.</p>`],
["mv", R`Was sagt das Spanner-Paper zu Transaktionen?`,
R`<p>Google argumentiert, es sei besser, wenn Anwendungsentwickler mit Performanceproblemen durch zu viele Transaktionen umgehen, als ständig um <b>fehlende</b> Transaktionen herum zu programmieren. Transaktionen gehören ins spezialisierte System, nicht in jede Anwendung.</p>`]
];

const deck = { id: "dbi", title: "DB-Implementierung", topics, cards: cards.map(([topic, q, a]) => ({ topic, q, a })) };
require("fs").writeFileSync(require("path").join(__dirname, "..", "decks", "dbi.json"), JSON.stringify(deck, null, 1));
console.log(deck.cards.length, topics.map(t => t.id + ":" + deck.cards.filter(c => c.topic === t.id).length).join(" "));
